--- Conformance tests against the independent Python reference oracle.
--
-- spec/fixtures/reference-cases.json is generated by
-- spec/tools/generate_reference_cases.py from Python's arbitrary-precision
-- integers, without consulting the Lua implementation. It covers timestamp and
-- entropy boundaries plus deterministic pseudo-random cases.

local json = require("spec.support.json")
local hex = require("spec.support.hex")
local pikaid = require("pikaid")

local FIXTURE_PATH = "spec/fixtures/reference-cases.json"

return function(t)
  local file = assert(io.open(FIXTURE_PATH, "rb"), "cannot open " .. FIXTURE_PATH)
  local document = json.decode(file:read("*a"))
  file:close()

  t.describe("independent reference oracle", function()
    t.it("documents a deterministic spec 1.0.4 case set", function()
      t.equal(document.meta.spec_revision, "1.0.4", "spec revision")
      t.equal(document.meta.seed, 20261106, "fixture seed")
      t.equal(#document.cases, 290, "case count")
    end)

    t.it("matches every reference case in both representations", function()
      for index, case in ipairs(document.cases) do
        local label = string.format("case %d %s", index, case.name)
        local randomness = hex.decode(case.randomness_hex)
        local binary = hex.decode(case.bin_hex)

        t.equal(#case.id, 26, label .. ": fixture id width")
        t.equal(#binary, 17, label .. ": fixture binary width")

        t.equal(pikaid.validate(case.id), true, label .. ": validate")
        t.equal(pikaid.is_well_formed(case.id), true, label .. ": shape")

        local parsed = pikaid.parse(case.id)
        t.equal(parsed.timestamp, case.timestamp, label .. ": timestamp")
        t.equal(parsed.randomness, randomness, label .. ": randomness bytes")
        t.equal(parsed.randomness_hex, case.randomness_hex, label .. ": randomness hex")

        t.equal(pikaid.to_binary(case.id), binary, label .. ": to_binary")
        t.equal(pikaid.from_binary(binary), case.id, label .. ": from_binary")

        local parsed_binary = pikaid.parse_binary(binary)
        t.equal(parsed_binary.timestamp, case.timestamp, label .. ": binary timestamp")
        t.equal(parsed_binary.randomness, randomness, label .. ": binary randomness")

        t.equal(pikaid.timestamp(case.id), case.timestamp, label .. ": accessor timestamp")
        t.equal(pikaid.randomness(case.id), randomness, label .. ": accessor randomness")
        t.equal(pikaid.validate_binary(binary), true, label .. ": validate_binary")
      end
    end)

    t.it("round-trips every identifier through binary and back", function()
      for index, case in ipairs(document.cases) do
        local label = string.format("case %d %s", index, case.name)

        t.equal(pikaid.from_binary(pikaid.to_binary(case.id)), case.id, label .. ": text/binary/text")
        t.equal(
          pikaid.to_binary(pikaid.from_binary(hex.decode(case.bin_hex))),
          hex.decode(case.bin_hex),
          label .. ": binary/text/binary"
        )
      end
    end)

    t.it("orders distinct timestamps chronologically in text and binary", function()
      local ordered = {}

      for _, case in ipairs(document.cases) do
        ordered[#ordered + 1] = case
      end

      table.sort(ordered, function(left, right)
        if left.timestamp == right.timestamp then
          return pikaid.compare(left.id, right.id) < 0
        end
        return left.timestamp < right.timestamp
      end)

      for index = 1, #ordered - 1 do
        local left = ordered[index]
        local right = ordered[index + 1]

        if left.timestamp ~= right.timestamp then
          local label = string.format("%d vs %d", left.timestamp, right.timestamp)

          t.equal(pikaid.compare(left.id, right.id), -1, "text " .. label)
          t.equal(pikaid.compare(right.id, left.id), 1, "text reversed " .. label)
          t.equal(
            pikaid.compare(hex.decode(left.bin_hex), hex.decode(right.bin_hex)),
            -1,
            "binary " .. label
          )
        end
      end
    end)

    t.it("keeps leading zero padding in both directions", function()
      for _, case in ipairs(document.cases) do
        if case.timestamp == 0 then
          t.equal(case.id:sub(1, 7), "0000000", case.name .. ": timestamp padding")
        end

        if case.randomness_hex == string.rep("0", 24) then
          t.equal(case.id:sub(8), string.rep("0", 19), case.name .. ": randomness padding")
        end
      end
    end)
  end)
end
